CREATE TABLE capability_aggregate_revisions (merchant_id text NOT NULL, capability text NOT NULL, aggregate_id text NOT NULL, revision integer NOT NULL CHECK(revision > 0), updated_at text NOT NULL, PRIMARY KEY(merchant_id, capability, aggregate_id));--> statement-breakpoint
CREATE TABLE capability_commands (command_key text PRIMARY KEY NOT NULL, merchant_id text NOT NULL, capability text NOT NULL, aggregate_id text NOT NULL, payload_fingerprint text NOT NULL, result_json text NOT NULL, revision integer NOT NULL, created_at text NOT NULL);--> statement-breakpoint
CREATE INDEX capability_commands_aggregate_idx ON capability_commands(merchant_id, aggregate_id);--> statement-breakpoint
CREATE TABLE capability_history (id text PRIMARY KEY NOT NULL, merchant_id text NOT NULL, aggregate_id text NOT NULL, revision integer NOT NULL, kind text NOT NULL, occurred_at text NOT NULL, UNIQUE(merchant_id, aggregate_id, revision));--> statement-breakpoint
CREATE TABLE capability_audit (id text PRIMARY KEY NOT NULL, merchant_id text NOT NULL, aggregate_id text NOT NULL, revision integer NOT NULL, actor_kind text NOT NULL, actor_id text NOT NULL, impersonation_id text, event_kind text NOT NULL, occurred_at text NOT NULL, UNIQUE(merchant_id, aggregate_id, revision));--> statement-breakpoint
CREATE TABLE capability_outbox (id text PRIMARY KEY NOT NULL, merchant_id text NOT NULL, aggregate_id text NOT NULL, revision integer NOT NULL, kind text NOT NULL, status text DEFAULT 'pending' NOT NULL CHECK(status IN ('pending','claimed','processed')), claimed_by text, claimed_at text, available_at text NOT NULL, processed_at text, created_at text NOT NULL, UNIQUE(merchant_id, aggregate_id, revision, kind));--> statement-breakpoint
CREATE INDEX capability_outbox_recovery_idx ON capability_outbox(status, available_at, claimed_at);
